dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "variant",
      "label": "Variant ID (CHR:POS:REF:ALT)",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "phewas_associations",
      "header": "PheWAS Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "phewas-associations",
        "parameters": [
          "variant"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "phenotype group",
        "phenotype map": "kp phenotype map",
        "y axis field": "pValue",
        "convert y -log10": "true",
        "y ticks decimal point": "2",
        "render by": "phenotype",
        "y axis label": "-Log10(p-value)",
        "x axis label": "beta",
        "beta field": "beta",
        "hover content": [
          "pValue",
          "beta"
        ],
        "thresholds": [
          "5e-8"
        ],
        "height": 600,
        "star key": "phenotype",
"plot margin":{"top":300,"bottom":300,"left":150,"right":175}
      }
    }
  ]
}
